macro_rules! deps {
    () => {
        FingerprintStyle!();
        DepKind!();
        DepNode!();
        DepContext!();
        DepNodeParams!();
    };
}

macro_rules! DepKindStruct {
    () => {
        deps!();
        # [doc = " This struct stores metadata about each DepKind."] # [doc = ""] # [doc = " Information is retrieved by indexing the `DEP_KINDS` array using the integer value"] # [doc = " of the `DepKind`. Overall, this allows to implement `DepContext` using this manual"] # [doc = " jump table instead of large matches."] pub struct DepKindStruct < Tcx : DepContext > { # [doc = " Anonymous queries cannot be replayed from one compiler invocation to the next."] # [doc = " When their result is needed, it is recomputed. They are useful for fine-grained"] # [doc = " dependency tracking, and caching within one compiler invocation."] pub is_anon : bool , # [doc = " Eval-always queries do not track their dependencies, and are always recomputed, even if"] # [doc = " their inputs have not changed since the last compiler invocation. The result is still"] # [doc = " cached within one compiler invocation."] pub is_eval_always : bool , # [doc = " Whether the query key can be recovered from the hashed fingerprint."] # [doc = " See [DepNodeParams] trait for the behaviour of each key type."] pub fingerprint_style : FingerprintStyle , # [doc = " The red/green evaluation system will try to mark a specific DepNode in the"] # [doc = " dependency graph as green by recursively trying to mark the dependencies of"] # [doc = " that `DepNode` as green. While doing so, it will sometimes encounter a `DepNode`"] # [doc = " where we don't know if it is red or green and we therefore actually have"] # [doc = " to recompute its value in order to find out. Since the only piece of"] # [doc = " information that we have at that point is the `DepNode` we are trying to"] # [doc = " re-evaluate, we need some way to re-run a query from just that. This is what"] # [doc = " `force_from_dep_node()` implements."] # [doc = ""] # [doc = " In the general case, a `DepNode` consists of a `DepKind` and an opaque"] # [doc = " GUID/fingerprint that will uniquely identify the node. This GUID/fingerprint"] # [doc = " is usually constructed by computing a stable hash of the query-key that the"] # [doc = " `DepNode` corresponds to. Consequently, it is not in general possible to go"] # [doc = " back from hash to query-key (since hash functions are not reversible). For"] # [doc = " this reason `force_from_dep_node()` is expected to fail from time to time"] # [doc = " because we just cannot find out, from the `DepNode` alone, what the"] # [doc = " corresponding query-key is and therefore cannot re-run the query."] # [doc = ""] # [doc = " The system deals with this case letting `try_mark_green` fail which forces"] # [doc = " the root query to be re-evaluated."] # [doc = ""] # [doc = " Now, if `force_from_dep_node()` would always fail, it would be pretty useless."] # [doc = " Fortunately, we can use some contextual information that will allow us to"] # [doc = " reconstruct query-keys for certain kinds of `DepNode`s. In particular, we"] # [doc = " enforce by construction that the GUID/fingerprint of certain `DepNode`s is a"] # [doc = " valid `DefPathHash`. Since we also always build a huge table that maps every"] # [doc = " `DefPathHash` in the current codebase to the corresponding `DefId`, we have"] # [doc = " everything we need to re-run the query."] # [doc = ""] # [doc = " Take the `mir_promoted` query as an example. Like many other queries, it"] # [doc = " just has a single parameter: the `DefId` of the item it will compute the"] # [doc = " validated MIR for. Now, when we call `force_from_dep_node()` on a `DepNode`"] # [doc = " with kind `MirValidated`, we know that the GUID/fingerprint of the `DepNode`"] # [doc = " is actually a `DefPathHash`, and can therefore just look up the corresponding"] # [doc = " `DefId` in `tcx.def_path_hash_to_def_id`."] pub force_from_dep_node : Option < fn (tcx : Tcx , dep_node : DepNode , prev_index : SerializedDepNodeIndex) -> bool > , # [doc = " Invoke a query to put the on-disk cached value in memory."] pub try_load_from_on_disk_cache : Option < fn (Tcx , DepNode) > , # [doc = " The name of this dep kind."] pub name : & 'static & 'static str , }
    };
}

DepKindStruct!()